mapper.select:
select * from category where user_id = #{categoryDTO.userId}
                                                            and name = #{categoryDTO.name}
                                                            and type = #{categoryDTO.type}
                                                            and ledger_id = #{ledgerId}

select id, user_id, name, type from category
                               where type = #{type}
                                 and user_id = #{userId}
                                and ledger_id = #{ledgerId}
                                              order by create_time desc

mapper.delete:
delete from category
       where user_id = #{userId} and ledger_id = #{ledgerId}
         and id in #{id}
